using System.Collections.Generic;
using System.Text;

namespace QuickJob.Generators;

/// <summary>产出 <c>QuickJobRegistrations.g.cs</c>：一个 <c>[ModuleInitializer]</c>，每个 job 一行
/// <c>PendingRegistrations.Add</c>。字段值按「写了且与记录默认不同」才发射，生成面越干净越好。</summary>
static class RegistrationEmitter
{
    public static string Render(IReadOnlyList<JobModel> jobs)
    {
        var sb = new StringBuilder();
        sb.Append("""
            // <auto-generated>QuickJob.Generators — compile-time [QuickJob] registrations.</auto-generated>
            #pragma warning disable CS8622, CS8624 // 方法组 → 委托的空档差异：签名形状已由生成器校验
            namespace QuickJob.Generated
            {
                [global::System.CodeDom.Compiler.GeneratedCode("QuickJob.Generators", "0.1.0")]
                internal static class __QuickJobRegistrations
                {
                    [global::System.Runtime.CompilerServices.ModuleInitializer]
                    internal static void Register()
                    {

            """);

        foreach (var job in jobs)
        {
            RenderOne(sb, job);
        }

        sb.Append("""
                    }
                }
            }
            #pragma warning restore CS8622, CS8624
            """);
        return sb.ToString();
    }

    static void RenderOne(StringBuilder sb, JobModel job)
    {
        sb.Append("            global::QuickJob.PendingRegistrations.Add(new global::QuickJob.PendingRegistration\n");
        sb.Append("            {\n");
        sb.Append("                Name = ").Append(Literal(job.Name)).Append(",\n");

        if (job.Cron is not null) sb.Append("                Cron = ").Append(Literal(job.Cron)).Append(",\n");
        if (job.Every is not null) sb.Append("                Every = ").Append(Literal(job.Every)).Append(",\n");
        if (job.TimeZone is not null) sb.Append("                TimeZone = ").Append(Literal(job.TimeZone)).Append(",\n");

        sb.Append("                HandlerFactory = () => ").Append(job.HandlerFactory).Append(",\n");

        if (job.MaxRetries != 0) sb.Append("                MaxRetries = ").Append(job.MaxRetries).Append(",\n");
        if (job.RetryBackoff is not null && job.RetryBackoff != "Exponential")
            sb.Append("                RetryBackoff = global::QuickJob.RetryBackoff.").Append(job.RetryBackoff).Append(",\n");
        if (job.RetryBaseDelay is not null) sb.Append("                RetryBaseDelay = ").Append(Literal(job.RetryBaseDelay)).Append(",\n");
        if (job.RetryMaxDelay is not null) sb.Append("                RetryMaxDelay = ").Append(Literal(job.RetryMaxDelay)).Append(",\n");
        if (job.RetryJitter != 0.25) sb.Append("                RetryJitter = ").Append(FormatDouble(job.RetryJitter)).Append(",\n");
        if (job.MaxConcurrentPerJob != 1) sb.Append("                MaxConcurrentPerJob = ").Append(job.MaxConcurrentPerJob).Append(",\n");
        if (job.OnOverlap is not null && job.OnOverlap != "Skip")
            sb.Append("                OnOverlap = global::QuickJob.OverlapPolicy.").Append(job.OnOverlap).Append(",\n");
        if (job.OverlapQueueLimit != 128) sb.Append("                OverlapQueueLimit = ").Append(job.OverlapQueueLimit).Append(",\n");
        if (job.Priority is not null && job.Priority != "Normal")
            sb.Append("                Priority = global::QuickJob.JobPriority.").Append(job.Priority).Append(",\n");
        if (job.OnMissedSlot is not null && job.OnMissedSlot != "RunWithinGrace")
            sb.Append("                OnMissedSlot = global::QuickJob.MissedSlotPolicy.").Append(job.OnMissedSlot).Append(",\n");
        if (job.Timeout is not null) sb.Append("                Timeout = ").Append(Literal(job.Timeout)).Append(",\n");
        if (job.Grace is not null) sb.Append("                Grace = ").Append(Literal(job.Grace)).Append(",\n");
        if (job.Description is not null) sb.Append("                Description = ").Append(Literal(job.Description)).Append(",\n");
        if (!job.Enabled) sb.Append("                Enabled = false,\n");

        sb.Append("            });\n");
    }

    /// <summary>invariant 字面量：小数点一位就够（jitter 只有 0–1 的相对量）。</summary>
    static string FormatDouble(double value)
        => value.ToString("0.###############", System.Globalization.CultureInfo.InvariantCulture);

    /// <summary>普通转义字面量：job 名与各种时长文本都是小 ASCII 面，引号/反斜杠/回车档收干净。</summary>
    static string Literal(string text)
    {
        var sb = new StringBuilder(text.Length + 8);
        sb.Append('"');
        foreach (var ch in text)
        {
            switch (ch)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default: sb.Append(ch); break;
            }
        }
        sb.Append('"');
        return sb.ToString();
    }
}
